   312|    // Supabase Management API has been observed to corrupt a space-separated uri_allow_list when
   313|    // multiple URLs are present, dropping the separator and concatenating values. To guarantee a
   314|    // valid allow-list for the new redirect URL, we REPLACE the list with exactly that URL.
   315|    const nextUrls = [redirectTo];
   316|    const nextAllowList = redirectTo;
