   318|    // PATCH using the correct Supabase field name uri_allow_list; keep site_url as the app base URL.
   319|    const patchBody = JSON.stringify({ uri_allow_list: nextAllowList, site_url: 'https://ivxholding.com' });
   320|    const patchResp = await fetch(authUrl, {
