   329|    }
   330|
   331|    // Re-read to verify
   332|    const getResp2 = await fetch(authUrl, { headers: { Authorization: `Bearer ${managementToken}`, Accept: 'application/json' } });
   333|    const getText2 = await getResp2.text();
   334|    const afterConfig = JSON.parse(getText2) as { uri_allow_list?: string; };
   335|    const afterUrls = typeof afterConfig.uri_allow_list === 'string'
